import { Injectable } from "@nestjs/common";
import { PluginBase } from "../../plugins/base-plugin";
import { PluginApi } from "../../plugins/api/plugin-api";
import { SkillLoaderService } from "../core/skill-loader.service";
import { SkillRegistry } from "../core/skill-registry.service";
import path from "path";

@Injectable()
export class SkillBundledPlugin extends PluginBase {
  manifest = {
    id: "skill-bundled",
    name: "内置技能",
    version: "1.0.0",
    description: "系统内置技能（skill-creator / skill-installer），可单独启停",
    category: "core",
  };

  constructor(
    private loader: SkillLoaderService,
    private registry: SkillRegistry,
  ) { super(); }

  async onLoad(api: PluginApi) {
    const bundledDir = path.join(process.cwd(), "bundled-skills");
    for (const name of ["skill-creator", "skill-installer"]) {
      try {
        const { manifest, body } = await this.loader.extractSkill(path.join(bundledDir, name));
        api.registerSkill({
          name, description: manifest.description, content: body,
          version: manifest.version, author: manifest.author, tags: manifest.tags,
          resourceBase: { kind: "directory", path: bundledDir },
        });
      } catch (err: any) {
        console.warn(`[skill-bundled] 注册内置技能失败 ${name}: ${err?.message || err}`);
      }
    }
  }

  /** 禁用时撤销本插件注册的全部技能 */
  async onStop() {
    this.registry.unregisterByProvider("plugin:skill-bundled");
  }
}
