实现：
```ts
/** 按会话插件启停过滤技能（对齐工具：插件关闭→搜集跳过） */
private filterByPlugins(skills: SkillDefinition[], session?: any): SkillDefinition[] {
  if (!session || typeof session.getResolvedPlugins !== "function") return skills;
  const plugins = session.getResolvedPlugins() as Array<{ plugin?: { id?: string }; enabled?: boolean }>;
  const enabledPluginIds = new Set(
    plugins.filter((p) => p.enabled).map((p) => p.plugin?.id).filter(Boolean),
  );
  const allPluginIds = new Set(plugins.map((p) => p.plugin?.id).filter(Boolean));
  return skills.filter((s) => {
    if (!s.provider || !s.provider.startsWith("plugin:")) return true; // file/workspace 技能不受插件启停影响
    const pluginId = s.provider.slice("plugin:".length);
    // 插件不在已决议列表（已卸载/不存在）或未启用 → 跳过
    return allPluginIds.has(pluginId) && enabledPluginIds.has(pluginId);
  });
}
```

